/*
 * A285177  0-limiting word of the morphism 0->11, 1->001.
 * https://oeis.org/A285177
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   0‑limiting word of the morphism 0→11, 1→001 (even iterations)
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* Static cache of the word generated by even numbers of iterations */
static uint8_t *bits = NULL;
static size_t cached_len = 0;
static unsigned int cached_iter = 0;   /* number of iterations applied so far */

/* Perform a single iteration of the morphism 0→11, 1→001. */
static void iter_one(void)
{
    size_t new_len = 0;
    for (size_t i = 0; i < cached_len; ++i)
        new_len += (bits[i] == 0) ? 2 : 3;

    uint8_t *new_bits = (uint8_t *)malloc(new_len);
    size_t pos = 0;
    for (size_t i = 0; i < cached_len; ++i) {
        if (bits[i] == 0) {          /* 0 → 11 */
            new_bits[pos++] = 1;
            new_bits[pos++] = 1;
        } else {                     /* 1 → 001 */
            new_bits[pos++] = 0;
            new_bits[pos++] = 0;
            new_bits[pos++] = 1;
        }
    }
    free(bits);
    bits = new_bits;
    cached_len = new_len;
    cached_iter++;
}

/* Return the nth term of A285177 (1‑based). */
seq_t a(idx_t n)
{
    if (n < 1)
        return (seq_t)0;

    /* Initialise the cache on first call. */
    if (bits == NULL) {
        bits = (uint8_t *)malloc(1);
        bits[0] = 0;
        cached_len = 1;
        cached_iter = 0;
    }

    size_t idx = (size_t)(n - 1);      /* 0‑based index */

    /* Grow the word until it contains the required index. */
    while (cached_len <= idx)
        iter_one();

    /* Ensure the stored word corresponds to an even number of iterations
       (0‑limiting word).  If the current iteration count is odd, perform
       one more iteration to reach the next even step. */
    if ((cached_iter & 1U) != 0)
        iter_one();

    return (seq_t)bits[idx];
}
